def main() -> None:
    rows = []
    with (ROOT / "materials" / "demo_questions.csv").open(encoding="utf-8-sig", newline="") as f:
        questions = {r["id"]: r["question"] for r in csv.DictReader(f)}
    with (ROOT / "materials" / "demo_output.csv").open(encoding="utf-8-sig", newline="") as f:
        goldens = {r["id"]: r["answer"] for r in csv.DictReader(f)}
    for qid, q in questions.items():
        cat, must, must_not = DEMO_META[qid]
        rows.append({"id": f"demo{int(qid):02d}", "category": cat, "question": q, "golden": goldens[qid],
                     "must": must, "must_not": must_not, "source": "organisers"})
    for x in X:
        rows.append(dict(x, source="team"))
    out = Path(__file__).resolve().parent / "devset.jsonl"
    with out.open("w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    cats = {}
    for r in rows:
        cats[r["category"]] = cats.get(r["category"], 0) + 1
    print(f"{len(rows)} questions -> {out.name}; categories: {dict(sorted(cats.items()))}")


if __name__ == "__main__":
    main()
